var mw = "https://www.mowan.lol";

function getCookie(k) {
    var java = this.java;
    var cookie = this.cookie;
    var cookieValue = String(cookie.getCookie(mw)) || String(java.getCookie(mw));
    var parts = cookieValue.split(";");
    for (var i = 0; i < parts.length; i++) {
        var part = parts[i].trim();
        var idx = part.indexOf(k + "=");
        if (idx === 0) {
            return part.substring(k.length + 1);
        }
    }
    return "";
}

function Api(url, method) {
    method = method || 'GET';
    var java = this.java;
    var XDeviceID = this.getCookie('X-Device-ID');
    var Authorization = this.getCookie('Authorization');
    if (typeof Authorization === 'string') {
        Authorization = Authorization.replace("%20", " ");
    } else {
        Authorization = String(Authorization).replace("%20", " ");
    }
    var options = {
        method: method,
        headers: JSON.stringify({
            'Authorization': Authorization,
            'X-Device-ID': XDeviceID,
            'Content-Type': 'application/json',
            'User-Agent': 'yuedu_app',
            'Referer': mw
        })
    };
    return mw + url + ',' + JSON.stringify(options);
}

function showPara(url) {
    var java = this.java;
    var cache = this.cache;
    var date = new Date().toLocaleDateString();
    var cacheKey = date + "dp";
    var htmlContent = cache.get(cacheKey);
    if (!htmlContent || String(htmlContent).indexOf("id=") === -1) {
        htmlContent = java.ajax(url);
        cache.put(cacheKey, htmlContent);
    }
    var browserConfig = {
        "expandedCornersRadius": 20,
        "dismissOnTouchOutside": true,
        "isDraggable": true,
        "shouldDimBackground": true,
        "backgroundDimAmount": 0.5,
        "hardwareAccelerated": true,
        "isNestedScrollingEnabled": true,
        "isGestureInsetBottomIgnored": true,
        "setFitToContents": true,
        "isHideable": true,
        "heightPercentage": 0.8
    };
    java.showBrowser(url, htmlContent, "window.java=java;", JSON.stringify(browserConfig));
}

function createBubble(number, url, bubble) {
    var num = number > 99 ? "99+" : number.toString();
    bubble = bubble.replace('$num', num);
    var encodedBubble = this.java.base64Encode(bubble);
    encodedBubble = 'data:image/svg+xml;base64,' + encodedBubble + ',{"click":"showPara(\'' + (mw + url) + '\' )","style":"text"}';
    return '<img src="' + encodedBubble + '">';
}

function showChapter(url) {
    var java = this.java;
    var cache = this.cache;
    var date = new Date().toLocaleDateString();
    var cacheKey = date + "end";
    var htmlContent = cache.get(cacheKey);
    if (!htmlContent || String(htmlContent).indexOf("id=") === -1) {
        htmlContent = java.ajax(url);
        cache.put(cacheKey, htmlContent);
    }
    var browserConfig = {
        "expandedCornersRadius": 20,
        "dismissOnTouchOutside": true,
        "isDraggable": true,
        "shouldDimBackground": true,
        "backgroundDimAmount": 0.5,
        "hardwareAccelerated": true,
        "isNestedScrollingEnabled": true,
        "isGestureInsetBottomIgnored": true,
        "setFitToContents": true,
        "isHideable": true,
        "heightPercentage": 0.8
    };
    java.showBrowser(url, htmlContent, "window.java=java;", JSON.stringify(browserConfig));
}

function createChapter(url, svg) {
    var encodedSvg = this.java.base64Encode(svg);
    encodedSvg = 'data:image/svg+xml;base64,' + encodedSvg + ',{"click":"showChapter(\'' + (mw + url) + '\' )","style":"FULL"}';
    return '<img src="' + encodedSvg + '">';
}

function show(k, v) {
    var java = this.java;
    var cache = this.cache;
    cache.put(v, k);
    java.refreshExplore();
}

function create(k, chars, defaultV, v, size) {
    return {
        title: k,
        type: "select",
        chars: chars,
        default: defaultV,
        action: 'show(infoMap[\'' + k + '\'],\'' + v + '\')',
        style: {
            layout_flexGrow: 1,
            layout_flexBasisPercent: size
        }
    };
}

function formatDate(input, fmt) {
    if (fmt === undefined) fmt = 'YYYY-MM-DD HH:mm:ss';
    var date = (input instanceof Date) ? input : new Date(input);
    if (isNaN(date.getTime())) return '';

    function pad(n) {
        var s = String(n);
        return s.length < 2 ? '0' + s : s;
    }

    var map = {
        YYYY: date.getFullYear(),
        MM: pad(date.getMonth() + 1),
        DD: pad(date.getDate()),
        HH: pad(date.getHours()),
        mm: pad(date.getMinutes()),
        ss: pad(date.getSeconds())
    };

    return fmt.replace(/YYYY|MM|DD|HH|mm|ss/g, function(m) {
        return map[m];
    });
}

function Env() {
    var java = this.java;
    var source = this.source;
    try {
        java.qread();
        return 4;
    } catch (e) {}
    try {
        if (typeof java.reLoginView === 'function') return 1;
        new Packages.io.legato.kazusa.utils.TimeoutCancellationException('');
        return 1;
    } catch (e) {}
    try {
        java.deviceID();
        return 3;
    } catch (e) {}
    if (typeof source.loginUi === 'function') return 2;
    return 1;
}

function Content(res) {
    var evn = this.Env();
    var content = "";
    var text = res.data.paragraphs;
    if (!text) {
        return res.data.msg || "暂无数据，请稍后再试~";
    }
    var enabledPara = res.data.comment.enabled;
    var bubble = enabledPara ? res.data.comment.bubble.svg : "";
    var enabledChapter = res.data.comment.chapter_enabled;
    var chapterSvgs = enabledChapter ? res.data.comment.chapter_card.svg : "";

    var contents = [];
    for (var i = 0; i < text.length; i++) {
        var item = text[i];
        var html = "";
        if (item.comment_count > 0 && enabledPara && bubble != '' && evn == 1) {
            html = '<p>' + item.text + this.createBubble(item.comment_count, item.comment_url, bubble) + '</p>';
        } else if (item.comment_count > 0 && enabledPara && bubble != '' && evn == 3) {
            html = '<div rs-native>' + item.text + '<comment count="' + item.comment_count + '" onPress="java.showReadingBrowser(\'' + (mw + item.comment_url) + '\',\'段评\')"></div>';
        } else {
            html = item.text;
        }
        if (item.image) {
            if (typeof item.image === 'string') {
                html += '<img src="' + item.image + '">';
            } else if (Array.isArray(item.image)) {
                for (var j = 0; j < item.image.length; j++) {
                    html += '<img src="' + item.image[j] + '">';
                }
            }
        }

        contents.push(html);
    }

    content = contents.join("\n");

    if (enabledChapter && chapterSvgs != "" && evn == 1) {
        var chapterUrl = res.data.comment.chapter_card.url;
        content += '\n' + this.createChapter(chapterUrl, chapterSvgs);
    } else if (enabledChapter && chapterSvgs != "" && evn == 3) {
        var chapterUrl = res.data.comment.chapter_card.url;
        var enChapterSvgs = java.base64Encode(chapterSvgs);
        content += '<div rs-native><img onPress="java.showReadingBrowser(\'' + (mw + chapterUrl) + '\',\'本章说\')" src="data:image/svg+xml;base64,' + enChapterSvgs + '"></div>';
    }

    return content;
}

